import _codecs
def handler(error):
    error.object = b'replaced'
    print('callback')
    raise AssertionError('continued after cancellation')
_codecs.register_error('replacement_cancel', handler)
try:
    _codecs.utf_8_decode(b'\xff', 'replacement_cancel', True)
except BaseException:
    raise AssertionError('caught cancellation')

